import { Group, Mesh, PlaneGeometry, MeshBasicNodeMaterial, MeshStandardNodeMaterial, Color, Box3 } from 'three/webgpu';
import { uv, vec2, vec3, mix, fract, sin, dot, add, mul, sub } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const root = new Group();
  root.userData.handlers = {};
  const timelines = [];

  // --- Backdrop ---
  const backdropGeo = new PlaneGeometry(7, 5.5);
  const backdropMat = new MeshBasicNodeMaterial();
  const st = uv();
  const color1 = vec3(0.043, 0.043, 0.063); // #0b0b10
  const color2 = vec3(0.075, 0.075, 0.102); // #13131a
  const gradient = mix(color1, color2, st.y);
  const grain = fract(sin(dot(mul(st, 100.0), vec2(12.9898, 78.233))) * 43758.5453123);
  const grainAmount = 0.015;
  const finalColor = add(gradient, mul(sub(mul(grain, 2.0), 1.0), grainAmount));
  backdropMat.colorNode = finalColor;
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.z = -1.5;
  root.add(backdrop);

  // --- Hero line: "TIME, MACHINED." ---
  const heroFull = ctx.fontAtlas.createText("TIME, MACHINED.", {
    fontSize: 124,
    color: '#e8ecf2',
    align: 'left',
    letterSpacingPx: -1.24  // -0.01em
  });

  // Extract individual glyph meshes
  const glyphMeshes = [];
  heroFull.traverse((child) => {
    if (child.isMesh) {
      glyphMeshes.push(child);
    }
  });
  // Remove from temporary group
  while (heroFull.children.length) heroFull.remove(heroFull.children[0]);

  // Scale from pixel to scene units (em height 0.62)
  glyphMeshes.forEach((mesh) => {
    mesh.scale.setScalar(0.005);
    mesh.position.multiplyScalar(0.005);
    mesh.material.transparent = true;
    mesh.material.opacity = 0;
    mesh.material.needsUpdate = true;
  });

  // Sort by x position (left to right)
  glyphMeshes.sort((a, b) => a.position.x - b.position.x);

  // Detect word boundary (space gap)
  let gapIndex = 0;
  for (let i = 0; i < glyphMeshes.length - 1; i++) {
    const diff = glyphMeshes[i + 1].position.x - glyphMeshes[i].position.x;
    if (diff > 0.03) {
      gapIndex = i + 1;
      break;
    }
  }

  // Apply per-word z offsets (front-to-back)
  for (let i = 0; i < glyphMeshes.length; i++) {
    if (i < gapIndex) {
      glyphMeshes[i].position.z = 0.12;
    } else {
      glyphMeshes[i].position.z = -0.12;
    }
  }

  // Build hero line group
  const heroLineGroup = new Group();
  glyphMeshes.forEach((mesh) => heroLineGroup.add(mesh));

  // Center the line horizontally
  const box = new Box3().setFromObject(heroLineGroup);
  const centerX = (box.min.x + box.max.x) / 2;
  heroLineGroup.position.x = -centerX;
  heroLineGroup.position.y = 0.4;
  root.add(heroLineGroup);

  // --- Cinematic primitive: kinetic-text ---
  const kineticResult = ctx.primitives['kinetic-text'](heroLineGroup, {
    staggerMs: 60,
    riseUnits: 0.35
  });
  timelines.push(kineticResult.timeline);

  // --- Weighted settle after final glyph ---
  const glyphCount = glyphMeshes.length;
  const settleDelay = (glyphCount - 1) * 0.06 + 0.7;
  const settleTL = gsap.timeline({ delay: settleDelay });
  settleTL
    .set(heroLineGroup.scale, { x: 1.04, y: 1.04, z: 1.04 })
    .to(heroLineGroup.scale, {
      x: 1,
      y: 1,
      z: 1,
      duration: 0.9,
      ease: 'cubic-bezier(0.165,0.84,0.44,1)'
    });
  timelines.push(settleTL);

  // --- Accent underline ---
  const underlineGeo = new PlaneGeometry(2.6, 0.045);
  underlineGeo.translate(1.3, 0, 0); // anchor left
  const underlineMat = new MeshStandardNodeMaterial();
  underlineMat.color = new Color('#ff2a38');
  underlineMat.emissive = new Color('#ff2a38');
  underlineMat.emissiveIntensity = 1.2;
  const underline = new Mesh(underlineGeo, underlineMat);
  underline.position.y = -0.05;
  underline.scale.x = 0;
  heroLineGroup.add(underline);

  const underlineDelay = settleDelay + 0.12;
  const underlineTL = gsap.to(underline.scale, {
    x: 1,
    duration: 0.5,
    delay: underlineDelay,
    ease: 'cubic-bezier(0.25,0.46,0.45,0.94)'
  });
  timelines.push(underlineTL);

  // --- Subhead ---
  const subheadText = ctx.fontAtlas.createText("Every calibre begins as a solid billet.", {
    fontSize: 40,
    color: '#e8ecf2',
    align: 'center',
    letterSpacingPx: 0.8   // 0.02em
  });
  subheadText.scale.setScalar(0.005);
  subheadText.position.y = -0.65; // final position
  // Set initial opacity and y offset for fade-up
  subheadText.traverse((child) => {
    if (child.isMesh) {
      child.material.transparent = true;
      child.material.opacity = 0;
      child.material.needsUpdate = true;
    }
  });
  root.add(subheadText);

  // Animate position and opacity
  const subheadPosTL = gsap.fromTo(subheadText.position, {
    y: -0.45
  }, {
    y: -0.65,
    duration: 0.5,
    ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
    delay: 0.5
  });
  timelines.push(subheadPosTL);

  subheadText.traverse((child) => {
    if (child.isMesh) {
      const matTL = gsap.to(child.material, {
        opacity: 1,
        duration: 0.5,
        ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
        delay: 0.5
      });
      timelines.push(matTL);
    }
  });

  // --- Caption ---
  const captionText = ctx.fontAtlas.createText("NOVA ATELIER / CALIBRE PROGRAM", {
    fontSize: 18,
    color: '#e8ecf2',
    align: 'center',
    letterSpacingPx: 2.16  // 0.12em
  });
  captionText.scale.setScalar(0.005);
  captionText.position.y = 1.15;
  root.add(captionText);

  // --- Cleanup ---
  root.userData.cleanup = () => {
    timelines.forEach((tl) => tl.kill());
    kineticResult.cleanup();
    // Dispose geometries and materials if needed
  };

  return root;
}
